@contextmanager
def extract(self, path, to_folder):
    root = ReentrantFileLock(to_folder()) if to_folder is not None else self.lock / "unzip" / __version__
    with root.lock_for_key(path.name):
        dest = root.path / path.name
        if not dest.exists():
            extract(path, dest)
        yield dest

